/** 件數合計：只有一種包裝單位時「3 CTNS」；混合時「2 PKGS (1 CASE + 1 CTN)」 */
function pkUnit(l){ return String(l.unit || "CTNS").trim().toUpperCase() || "CTNS"; }
function pkTotal(lines){
  const by = {}; let t = 0; (lines||[]).forEach(l => { const c = Number(l.ctn)||0; if (!c) return; const u = pkUnit(l); by[u] = (by[u]||0) + c; t += c; });
  const us = Object.keys(by); if (us.length <= 1) return `${fmt(t)} ${us[0] || "CTNS"}`;
  return `${fmt(t)} PKGS (${us.map(u => `${fmt(by[u])} ${u}`).join(" + ")})`;
}

